create policy "action_jobs_select_scoped"
on public.action_jobs
for select
to authenticated
using (
  public.current_user_has_platform_role()
  or public.current_user_has_partner_role(partner_id)
  or public.current_user_has_partner_client_role(partner_id, client_id)
);

create policy "integration_connections_select_accessible"
on public.integration_connections
for select
to authenticated
using (
  public.current_user_has_platform_role()
  or public.current_user_has_partner_role(partner_id)
  or public.current_user_has_client_role(client_id)
);

create policy "integration_connections_update_authorized"
on public.integration_connections
for update
to authenticated
using (
  public.current_user_has_platform_role(array[
    'platform_owner',
    'platform_admin'
  ]::public.membership_role[])
  or public.current_user_has_partner_role(partner_id, array[
    'partner_owner',
    'partner_admin',
    'partner_implementer'
  ]::public.membership_role[])
)
with check (
  public.current_user_has_platform_role(array[
    'platform_owner',
    'platform_admin'
  ]::public.membership_role[])
  or public.current_user_has_partner_role(partner_id, array[
    'partner_owner',
    'partner_admin',
    'partner_implementer'
  ]::public.membership_role[])
);

create policy "integration_canonical_records_select_scoped"
on public.integration_canonical_records for select to authenticated
using (
  public.current_user_has_platform_role()
  or public.current_user_has_partner_role(partner_id)
  or public.current_user_has_client_role(client_id, array[
    'client_owner', 'client_manager'
  ]::public.membership_role[])
);

